WFJ.Data.add("spell", {
  [468012] = { "Infligge danni normali e $N1 danni aggiuntivi ai nemici vicini, impedendo il lancio d'incantesimi per $D1.", "Impossibile lanciare incantesimi.", 0x40a0b6a6, 0x6d133d61, "uu" },
  [468027] = { nil, "$N1 danni da natura inflitti ogni $D1.", nil, 0xf6322bec, "mu" },
  [468028] = { "Mentre hai come bersaglio un nemico entro $N1 m, ⟦Life Tap=Conversione Vitale⟧ ti conferisce mana a spese della salute del bersaglio, ma gli infligge il $N2% di danni in meno. Il mana ottenuto resta invariato.", nil, 0xd7c41828, nil, "um" },
  [468046] = { "Mentre Metamorfosi è attiva, le tue abilità offensive e le evocazioni di demoni non costano frammenti d'anima. Inoltre, ti curi del $N1% della tua salute massima quando danneggi un bersaglio con Combustione dell'Ombra.", nil, 0x3233cdd9, nil, "um" },
  [468061] = { "Le cure in eccesso che ricevi da te stesso vengono convertite in uno scudo che assorbe i danni. Questo scudo può assorbire fino al $N1% della tua salute massima e si accumula con più cure.", nil, 0xdcc102be, nil, "um" },
  [468065] = { "Ottieni $N1 rabbia ogni volta che pari o che uno dei tuoi attacchi viene parato.", nil, 0x08c9664b, nil, "um" },
  [468067] = { "Rivincita ti conferisce anche Raffica di Colpi, che aumenta la tua velocità d'attacco del $N1% per i prossimi $N2 colpi.", nil, 0x8d2b9dbc, nil, "um" },
  [468069] = { "Quando il tuo bersaglio para un attacco, esegui istantaneamente una Reazione contro di lui che infligge il $N1% dei danni dell'arma. Reazione non può essere schivata, bloccata o parata, ma può verificarsi solo una volta ogni $D1 per bersaglio.", nil, 0x9be3acfc, nil, "um" },
  [468072] = { "I colpi critici di Dominazione riportano al massimo la durata di Squartamento sul tuo bersaglio.", nil, 0x29869854, nil, "um" },
  [468076] = { "Aumenta del $N1% i danni subiti da Assalto Feroce", "Aumenta del $N1% i danni subiti da Assalto Feroce", 0xb9584819, 0xb9584819, "uu" },
  [468078] = { nil, "Annullato.", nil, 0xcab37784, "mu" },
  [468125] = { "Infondi di magia la Depleted Essence of Fire.", nil, 0x2a35ab25, nil, "um" },
